traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?dev ;
         rdfs:label ?label .
  ?dev a net:NetworkDevice ;
       rdfs:label "Edge Firewall FW1" .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?alarmLabel
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?alarmLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>

SELECT ?rootAlarm ?alarmType ?severity ?device
WHERE {
  net:Incident_DDoS net:composedOf ?rootAlarm .
  ?rootAlarm net:alarmType ?alarmType ;
             net:hasSeverity ?severity .
  OPTIONAL { ?rootAlarm net:affectsDevice ?device . }
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?rootAlarm .
  }
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCauseLabel WHERE {
  BIND(net:Alarm_WebTimeout AS ?target)
  ?target net:causallyLinkedTo* ?rootCause .
  FILTER NOT EXISTS { ?rootCause net:causallyLinkedTo ?any . }
  ?rootCause rdfs:label ?rootCauseLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?causeLabel WHERE {
  ?cause net:causallyLinkedTo net:Alarm_Latency .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?alarm .
  ?alarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(?intermediate) AS ?pathLength) WHERE {
  net:Alarm_CPU net:causallyLinkedTo+ net:Alarm_WebTimeout .
  OPTIONAL { net:Alarm_CPU net:causallyLinkedTo ?intermediate .
             ?intermediate net:causallyLinkedTo+ net:Alarm_WebTimeout . }
} LIMIT 1

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_Latency net:causallyLinkedTo+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS {
    ?anyAlarm net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  ?cause net:causallyLinkedTo ?effect .
  FILTER(?cause = net:Alarm_Latency && ?effect = net:Alarm_PacketDrop ||
         ?cause = net:Alarm_PacketDrop && ?effect = net:Alarm_Latency)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  net:Alarm_PacketDrop net:correlatedWith ?alarm .
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
SELECT ?affectedAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?affectedAlarm .
  ?affectedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?avoidedAlarm ?label WHERE {
  net:Alarm_CPU net:causallyLinkedTo ?avoidedAlarm .
  ?avoidedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?affectedAlarm) AS ?preventedAlarms)
WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo ?affectedAlarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?remainingAlarm ?type ?severity ?device
WHERE {
  # incident and its alarms
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm net:alarmType ?type ;
         net:hasSeverity ?severity ;
         net:affectsDevice ?device .

  # identify the CPU overload alarm
  BIND(net:Alarm_CPU AS ?cpuAlarm)

  # find alarms that are causally downstream of the CPU alarm
  OPTIONAL {
    ?cpuAlarm net:causallyLinkedTo+ ?downstream .
    FILTER(?alarm = ?downstream)
  }

  # keep alarms that are not downstream of the CPU alarm
  FILTER(!BOUND(?downstream))

  BIND(?alarm AS ?remainingAlarm)
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_Latency net:causallyLinkedTo net:Alarm_WebTimeout .
}
